from typing import Protocol, runtime_checkable

@runtime_checkable
class VectorProtocol(Protocol):
    """Minimal interface contract for a vector."""
    def __len__(self) -> int: ...
    def __getitem__(self, index: int) -> float: ...
    def __iter__(self): ...

@runtime_checkable
class MatrixProtocol(Protocol):
    """Minimal interface contract for a matrix."""
    def __len__(self) -> int: ...
    def __getitem__(self, index: int) -> VectorProtocol: ...
